//! `spec/transport.golden`, built into the crate, and a reader for it.
//!
//! The constants in [`crate::layout`] are checked against this text in the
//! tests, and [`LAYOUT_HASH`] is its hash line. The inspector also uses the
//! reader to decode records of every kind by their layouts.

/// The golden file, as generated by `cargo xtask spec`.
pub const GOLDEN: &str = include_str!("../../../spec/transport.golden");

/// The 16 hex digits of the golden file's hash line, read as one number.
pub const LAYOUT_HASH: u64 = hash_line(GOLDEN);

const fn hash_line(text: &str) -> u64 {
    let b = text.as_bytes();
    // The hash line is the last line: "hash " and 16 hex digits.
    let mut end = b.len();
    while end > 0 && b[end - 1] == b'\n' {
        end -= 1;
    }
    assert!(end >= 21, "the golden file ends in its hash line");
    let start = end - 16;
    assert!(
        b[start - 5] == b'h'
            && b[start - 4] == b'a'
            && b[start - 3] == b's'
            && b[start - 2] == b'h'
            && b[start - 1] == b' ',
        "the golden file ends in its hash line"
    );
    let mut value = 0u64;
    let mut i = start;
    while i < end {
        let d = match b[i] {
            c @ b'0'..=b'9' => c - b'0',
            c @ b'a'..=b'f' => c - b'a' + 10,
            _ => panic!("the hash line holds lower-case hex digits"),
        };
        value = value << 4 | d as u64;
        i += 1;
    }
    value
}

/// A fixed field of a layout.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Field<'a> {
    /// Offset from the start of the structure.
    pub offset: usize,
    /// `u32`, `u64`, `f64`, `u64[32]`, `pad[24]` and so on.
    pub ty: &'a str,
    /// The field's name.
    pub name: &'a str,
    /// `agent` or `sidecar`, for the status block only.
    pub writer: Option<&'a str>,
}

impl Field<'_> {
    /// The element type and count: `u64[32]` is (`u64`, 32), `u32` is (`u32`, 1).
    /// A `pad[N]` is (`pad`, N).
    pub fn element(&self) -> (&str, usize) {
        match self.ty.split_once('[') {
            Some((t, n)) => (t, n.trim_end_matches(']').parse().unwrap_or(0)),
            None => (self.ty, 1),
        }
    }

    /// Bytes the field takes.
    pub fn size(&self) -> usize {
        let (t, n) = self.element();
        n * width(t).unwrap_or(1)
    }
}

/// The bytes of one value of a fixed-width type, or `None` for a variable one.
pub fn width(ty: &str) -> Option<usize> {
    match ty {
        "u8" | "pad" => Some(1),
        "u16" => Some(2),
        "u32" | "f32" => Some(4),
        "u64" | "f64" => Some(8),
        _ => None,
    }
}

/// A variable part that follows a layout's fixed fields.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Variable<'a> {
    /// `str`, `lv`, `tlv[n]`, `u64[n]` and so on.
    pub ty: &'a str,
    /// The part's name.
    pub name: &'a str,
}

/// One `layout` section.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Layout<'a> {
    /// The layout's name: `status`, `record`, `command`, a record kind or an
    /// opcode.
    pub name: &'a str,
    /// Bytes of fixed fields.
    pub fixed: usize,
    /// The fixed fields in order.
    pub fields: Vec<Field<'a>>,
    /// The variable parts in order.
    pub variable: Vec<Variable<'a>>,
}

impl<'a> Layout<'a> {
    /// The fixed field named `name`.
    pub fn field(&self, name: &str) -> Option<&Field<'a>> {
        self.fields.iter().find(|f| f.name == name)
    }
}

/// One row of a `codes` section.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Code<'a> {
    /// The number.
    pub code: u64,
    /// The name.
    pub name: &'a str,
    /// The other columns, as `key=value`.
    pub attrs: Vec<(&'a str, &'a str)>,
}

impl Code<'_> {
    /// The value of the column `key`.
    pub fn attr(&self, key: &str) -> Option<&str> {
        self.attrs.iter().find(|(k, _)| *k == key).map(|(_, v)| *v)
    }
}

/// The layout named `name` in the golden file.
pub fn layout(name: &str) -> Option<Layout<'static>> {
    let mut lines = GOLDEN.lines();
    let (name, fixed) = loop {
        let line = lines.next()?;
        if let Some((n, f)) = line.strip_prefix("layout ").and_then(|r| r.split_once(' '))
            && n == name
        {
            break (n, f.strip_prefix("fixed=")?.parse().ok()?);
        }
    };
    let mut out = Layout {
        name,
        fixed,
        fields: Vec::new(),
        variable: Vec::new(),
    };
    for line in lines {
        let Some(row) = line.strip_prefix("  ") else {
            break;
        };
        let mut cols = row.split(' ');
        let first = cols.next()?;
        if first == "+" {
            out.variable.push(Variable {
                ty: cols.next()?,
                name: cols.next()?,
            });
        } else {
            let offset = usize::from_str_radix(first.strip_prefix("0x")?, 16).ok()?;
            out.fields.push(Field {
                offset,
                ty: cols.next()?,
                name: cols.next()?,
                writer: cols.next(),
            });
        }
    }
    Some(out)
}

/// The rows of the codes section named `name`, empty when there is none.
pub fn codes(name: &str) -> Vec<Code<'static>> {
    let mut lines = GOLDEN.lines();
    let header = format!("codes {name}");
    if !lines.by_ref().any(|l| l == header) {
        return Vec::new();
    }
    let mut out = Vec::new();
    for line in lines {
        let Some(row) = line.strip_prefix("  ") else {
            break;
        };
        let mut cols = row.split(' ');
        let (Some(code), Some(name)) = (cols.next(), cols.next()) else {
            break;
        };
        let Ok(code) = code.parse() else { break };
        out.push(Code {
            code,
            name,
            attrs: cols.filter_map(|c| c.split_once('=')).collect(),
        });
    }
    out
}

/// The name of code `code` in section `section`.
pub fn code_name(section: &str, code: u64) -> Option<&'static str> {
    codes(section)
        .into_iter()
        .find(|c| c.code == code)
        .map(|c| c.name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_hash_is_the_last_line() {
        let last = GOLDEN.lines().last().expect("a line");
        assert_eq!(last, format!("hash {LAYOUT_HASH:016x}"));
    }

    #[test]
    fn layouts_and_codes_are_read() {
        let status = layout("status").expect("status");
        assert_eq!(status.fixed, 4096);
        assert_eq!(status.field("ready").map(|f| f.offset), Some(0x60));
        assert_eq!(
            status.field("in_tail").and_then(|f| f.writer),
            Some("sidecar")
        );
        let hello = layout("HELLO").expect("HELLO");
        assert_eq!(hello.variable[0].name, "dcs_version");
        let kinds = codes("record_kind");
        assert_eq!(kinds[1].name, "FRAME");
        assert_eq!(kinds[1].attr("class"), Some("control"));
        assert_eq!(code_name("lifecycle", 3), Some("RUNNING"));
        assert!(layout("nothing").is_none());
        assert!(codes("nothing").is_empty());
    }

    #[test]
    fn every_field_size_is_known() {
        for line in GOLDEN.lines() {
            if let Some(rest) = line.strip_prefix("layout ") {
                let name = rest.split(' ').next().expect("a name");
                let l = layout(name).expect("the layout");
                let mut at = 0;
                for f in &l.fields {
                    assert_eq!(f.offset, at, "{name}.{}", f.name);
                    at += f.size();
                }
                assert_eq!(at, l.fixed, "{name}");
            }
        }
    }
}
